cells={(0,1),(0,2),(0,4),(0,5),(1,0),(1,1),(1,2),(1,3),(1,4),(1,5),(2,1),(2,2),(2,4),(3,2),(3,3),(3,4)}
pieces=[]
# square
for r in range(4):
 for c in range(6):
  p={(r,c),(r+1,c),(r,c+1),(r+1,c+1)}
  if p<=cells: pieces.append(('S',p))
# L triominoes: any 3 corners of 2x2
for r in range(4):
 for c in range(6):
  q={(r,c),(r+1,c),(r,c+1),(r+1,c+1)}
  for miss in q:
   p=q-{miss}
   if p<=cells: pieces.append(('L'+('TL' if miss==(r,c) else 'TR' if miss==(r,c+1) else 'BL' if miss==(r+1,c) else 'BR'),p))
sol=[]
def go(left,chosen,squares):
 if not left:
  if squares==1: sol.append(chosen)
  return
 if squares>1:return
 cell=min(left)
 for typ,p in pieces:
  if cell in p and p<=left:
   go(left-p,chosen+[(typ,p)],squares+(typ=='S'))
go(cells,[],0)
print('solutions',len(sol))
for s in sol[:30]:
 print('---')
 for typ,p in s: print(typ, sorted(p))
